import { pageMember } from "@/lib/page";
import { todayIn } from "@/lib/time";
import { CheckInDesk } from "@/components/CheckInDesk";

export const metadata = { title: "Check-in" };

export default async function CheckInPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const { business } = await pageMember(slug, "checkin");
  return (
    <div className="mx-auto max-w-xl space-y-4">
      <h1 className="text-3xl font-extrabold">Check-in</h1>
      <CheckInDesk businessId={business.id} slug={slug} today={todayIn(business.timezone)} />
    </div>
  );
}
